        "alts": [ { "zh": "請問這次主要的目標受眾是哪一群人呢？", "py": "Qǐngwèn zhè cì zhǔyào de mùbiāo shòuzhòng shì nǎ yì qún rén ne?" } ],
        "distractors": [ "你們的包裝要賣給誰？", "請問這次包裝是要賣給什麼人們？" ],
